"""
build_baogia.py — Halo Media Báo Giá Builder
Dùng trong Claude Project Chat: Claude chạy script này để xuất file xlsx báo giá.

CÁCH DÙNG:
  Truyền dict DATA vào hàm build_baogia(data, logo_path, output_path)
  hoặc chạy trực tiếp với DATA mẫu ở cuối file.
"""

import os
import json
import shutil
import urllib.request
from datetime import date
from openpyxl import Workbook
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
from openpyxl.drawing.image import Image as XLImage
from openpyxl.utils import get_column_letter

# ── Cấu hình URL logo (fetch tự động, không cần file local) ───────────────────
LOGO_URL = "https://drive.google.com/uc?export=download&id=1j1SWR5bVJ4mg7BiU8vGm-rCtLbzkA3pH"
LOGO_TMP = "/tmp/logo_hpb.png"
LOGO_B64 = ""


SO_LIEN_TUC_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "so-lien-tuc.json")

# ── Helper: fetch logo từ URL về /tmp ─────────────────────────────────────────
def fetch_logo(url=LOGO_URL, dest=LOGO_TMP):
    """Decode logo từ base64 nhúng sẵn. Fallback fetch URL nếu cần."""
    import base64
    try:
        with open(dest, "wb") as f:
            f.write(base64.b64decode(LOGO_B64))
        return dest
    except Exception:
        pass
    try:
        urllib.request.urlretrieve(url, dest)
        return dest
    except Exception as e:
        print(f"⚠️  Không tải được logo: {e}")
        return None

# ── Helper: đọc & tăng số liên tục ───────────────────────────────────────────
def next_so_bao_gia(json_path=SO_LIEN_TUC_PATH):
    """Đọc so-lien-tuc.json, tăng số báo giá, ghi lại, trả về số mới."""
    try:
        with open(json_path, encoding="utf-8") as f:
            d = json.load(f)
        so_cu = d.get("so_bao_gia_cuoi", "BG-WEB-000")
        parts = so_cu.rsplit("-", 1)
        if len(parts) == 2 and parts[1].isdigit():
            pad = max(len(parts[1]), 4)
            new_so = f"{parts[0]}-{str(int(parts[1]) + 1).zfill(pad)}"
        else:
            new_so = so_cu + "-001"
        d["so_bao_gia_cuoi"] = new_so
        d["cap_nhat_lan_cuoi"] = date.today().strftime("%d/%m/%Y")
        with open(json_path, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
        return new_so
    except Exception as e:
        print(f"⚠️  Không đọc được so-lien-tuc.json: {e}")
        return "BG-WEB-001"

# ── Màu sắc chuẩn Halo Media ──────────────────────────────────────────────────
BLUE       = "0068B8"
ORANGE     = "F97316"
WHITE      = "FFFFFF"
LIGHT_BLUE = "EBF4FB"
LIGHT_GRAY = "F5F5F5"
MID_GRAY   = "D9D9D9"
DARK_TEXT  = "1A1A1A"
SUB_TEXT   = "555555"

# ── Helpers ────────────────────────────────────────────────────────────────────
def _font(name="Arial", size=10, bold=False, color=DARK_TEXT, italic=False):
    return Font(name=name, size=size, bold=bold, color=color, italic=italic)

def _fill(hex_color):
    return PatternFill("solid", fgColor=hex_color)

def _align(h="left", v="center", wrap=False):
    return Alignment(horizontal=h, vertical=v, wrap_text=wrap)

def _border(top=True, bottom=True, left=True, right=True, color="CCCCCC"):
    s = Side(style="thin", color=color)
    n = Side(style=None)
    return Border(
        top=s if top else n,
        bottom=s if bottom else n,
        left=s if left else n,
        right=s if right else n,
    )

def _mc(ws, rng, val=None, fnt=None, aln=None, fll=None, brd=None):
    """Merge cells + format top-left."""
    ws.merge_cells(rng)
    c = ws[rng.split(":")[0]]
    if val is not None: c.value = val
    if fnt: c.font = fnt
    if aln: c.alignment = aln
    if fll: c.fill = fll
    if brd: c.border = brd
    return c

def _set_row(ws, r, height=None):
    ws.row_dimensions[r].height = height  # None = Excel auto

def _auto_height(text, col_width_chars=52, line_height=14, padding=8):
    """Tính row height dựa theo nội dung + padding trên/dưới."""
    if not text:
        return line_height + padding
    lines = 0
    for para in str(text).split("\n"):
        if para.strip() == "":
            lines += 0.5  # dòng trống tính nhẹ
        else:
            char_per_line = max(col_width_chars, 1)
            lines += max(1, -(-len(para) // char_per_line))  # ceiling div
    return int(lines * line_height + padding)

# ── Hàm build chính ───────────────────────────────────────────────────────────
def build_baogia(data: dict, logo_path: str = None, output_path: str = None):
    """
    data dict gồm các key:
      THÔNG TIN BÁO GIÁ:
        so_bao_gia       : str   — VD: "BG-WEB-001"
        ngay_bao_gia     : str   — VD: "04/04/2026" (mặc định: hôm nay)
        loai_dich_vu     : str   — VD: "THIẾT KẾ WEBSITE"
        ten_du_an        : str   — VD: "Website Công Ty ABC"

      THÔNG TIN KHÁCH HÀNG:
        ten_khach_hang   : str
        nguoi_dai_dien   : str
        sdt_khach        : str
        email_khach      : str
        dia_chi_khach    : str
        mst_khach        : str   — để trống nếu không có
        loai_website     : str   — VD: "Website giới thiệu doanh nghiệp"
        so_trang         : str   — VD: "7"
        thoi_gian        : str   — VD: "15 ngày làm việc"

      HẠNG MỤC (list of dict):
        hang_muc: [
          {
            "stt"       : "1" hoặc "1.1",
            "ten"       : "Thiết kế Website",
            "chi_tiet"  : "Nội dung chi tiết...",
            "don_gia"   : 8000000,   # số int/float, 0 = bao gồm trong gói
            "ghi_chu"   : "Thanh toán 1 lần",
            "is_sub"    : False,     # True = row phụ (1.1, 1.2...)
          },
          ...
        ]
    """
    # Output path — fallback nếu không truyền vào
    if output_path is None:
        outputs_dir = "/mnt/user-data/outputs" if os.path.exists("/mnt/user-data/outputs") else "."
        ten_kh = data.get("ten_khach_hang", "KhachHang").replace(" ", "")[:20]
        ngay_fn = date.today().strftime("%d%m%Y")
        output_path = os.path.join(outputs_dir, f"BaoGia-{ten_kh}-{ngay_fn}.xlsx")

    # Logo — ưu tiên logohpb.png trong thư mục skill, rồi mới fetch từ URL
    skill_logo = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "logohpb.png")
    if not logo_path or not os.path.exists(logo_path):
        if os.path.exists(skill_logo):
            logo_path = skill_logo
        else:
            logo_path = fetch_logo()

    wb = Workbook()
    ws = wb.active
    ws.title = "Báo Giá"
    ws.sheet_view.showGridLines = False

    # Page setup A4 landscape
    ws.page_setup.orientation = "landscape"
    ws.page_setup.paperSize = ws.PAPERSIZE_A4
    ws.page_setup.fitToPage = True
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0

    # Cột: A=STT B=Hạng mục C=Chi tiết D=Đơn giá E=Thành tiền F=Ghi chú
    for col, w in [("A",6),("B",20),("C",36),("D",14),("E",14),("F",22)]:
        ws.column_dimensions[col].width = w

    # Giá trị mặc định
    ngay = data.get("ngay_bao_gia") or date.today().strftime("%d/%m/%Y")
    so_bg = data.get("so_bao_gia", "BG-WEB-001")

    # ── ROW 1: Logo + Thông tin công ty ────────────────────────────────────────
    _set_row(ws, 1, 60)

    _mc(ws, "A1:B1",
        fll=_fill(WHITE),
        aln=_align("center","center"))

    # Nhúng logo nếu có — giữ nguyên độ phân giải gốc, chỉ thu nhỏ display size
    if logo_path and os.path.exists(logo_path):
        from PIL import Image as PILImage
        # Đọc ảnh gốc, convert sang RGBA để nền trong suốt
        pil_img = PILImage.open(logo_path).convert("RGBA")
        orig_w, orig_h = pil_img.size
        # Ghi ra file tạm PNG ở độ phân giải gốc (không resize → không mờ)
        tmp_logo = "/tmp/logo_final.png"
        pil_img.save(tmp_logo, "PNG", optimize=False)
        # Display size: cao 52px, giữ tỉ lệ
        display_h = 52
        display_w = int(orig_w * display_h / orig_h)
        img = XLImage(tmp_logo)
        img.width = display_w
        img.height = display_h

        # Căn giữa logo: dùng OneCellAnchor với offset EMU
        from openpyxl.drawing.spreadsheet_drawing import OneCellAnchor, AnchorMarker
        from openpyxl.utils.units import pixels_to_EMU

        row_h_px = 60
        col_ab_px = int((6 + 20) * 7.5)

        off_x = pixels_to_EMU(max((col_ab_px - display_w) // 2, 4))
        off_y = pixels_to_EMU(max((row_h_px - display_h) // 2, 4))

        marker = AnchorMarker(col=0, colOff=off_x, row=0, rowOff=off_y)

        anchor = OneCellAnchor(_from=marker, ext=None)
        from openpyxl.drawing.xdr import XDRPositiveSize2D
        anchor.ext = XDRPositiveSize2D(pixels_to_EMU(display_w), pixels_to_EMU(display_h))
        img.anchor = anchor
        ws.add_image(img)
        ws["A1"].value = None
    else:
        ws["A1"].value = "HPB MEDIA"
        ws["A1"].font = _font(size=11, bold=True, color="0068B8")
        ws["A1"].alignment = _align("center","center")

    # Header công ty: dòng 1 bold, dòng 2-3 normal + hyperlinks
    ws.merge_cells("C1:F1")
    c1 = ws["C1"]
    c1.fill = _fill(WHITE)
    c1.alignment = _align("left", "center", wrap=True)

    from openpyxl.cell.text import InlineFont
    from openpyxl.cell.rich_text import TextBlock, CellRichText

    bold_font   = InlineFont(rFont='Arial', b=True, sz=9, color=DARK_TEXT)
    normal_font = InlineFont(rFont='Arial', b=False, sz=9, color=DARK_TEXT)
    link_font   = InlineFont(rFont='Arial', b=False, sz=9, color="0068B8", u="single")

    c1.value = CellRichText(
        TextBlock(bold_font,   "HPB MEDIA — Thiết kế website & Digital Marketing\n"),
        TextBlock(normal_font, "SĐT: "),
        TextBlock(link_font,   "0913 337 280"),
        TextBlock(normal_font, "  |  Email: "),
        TextBlock(link_font,   "hungphamcqb@gmail.com"),
    )

    # ── ROW 2: Số BG + Ngày ────────────────────────────────────────────────────
    _set_row(ws, 2, 20)
    _mc(ws, "A2:F2",
        val=f"Số BG: {so_bg}   |   Ngày: {ngay}",
        fnt=_font(size=9, color=SUB_TEXT, italic=True),
        aln=_align("right","center"),
        fll=_fill(WHITE))

    # ── ROW 3: Tiêu đề ─────────────────────────────────────────────────────────
    _set_row(ws, 3, 38)
    _mc(ws, "A3:F3",
        val=f"BÁO GIÁ {data.get('loai_dich_vu','THIẾT KẾ WEBSITE').upper()}",
        fnt=_font(size=18, bold=True, color=WHITE),
        aln=_align("center","center"),
        fll=_fill(BLUE))

    # ── ROW 4: Tên dự án ───────────────────────────────────────────────────────
    _set_row(ws, 4, 22)
    _mc(ws, "A4:F4",
        val=data.get("ten_du_an",""),
        fnt=_font(size=11, bold=True, color=BLUE),
        aln=_align("center","center"),
        fll=_fill(LIGHT_BLUE))

    # ── ROW 5: Header thông tin khách ──────────────────────────────────────────
    _set_row(ws, 5, 24)
    _mc(ws, "A5:F5",
        val="THÔNG TIN KHÁCH HÀNG",
        fnt=_font(size=9, bold=True, color=WHITE),
        aln=_align("left","center"),
        fll=_fill(BLUE))

    # ── ROWS 6-10: Thông tin khách ─────────────────────────────────────────────
    loai_ws = data.get('loai_website', '')
    nen_tang = data.get('nen_tang', 'WordPress')
    loai_val = f"{loai_ws}   |   Nền tảng: {nen_tang}" if nen_tang else loai_ws

    so_trang = data.get('so_trang', '')
    thoi_gian = data.get('thoi_gian', '')
    tien_do_val = f"{so_trang} trang   |   Thời gian dự kiến: {thoi_gian}" if so_trang else f"Thời gian dự kiến: {thoi_gian}"

    kh = [
        ("Khách hàng:",          data.get("ten_khach_hang","")),
        ("Người đại diện:",
            f"{data.get('nguoi_dai_dien','')}   |   SĐT: {data.get('sdt_khach','')}   |   Email: {data.get('email_khach','')}"),
        ("Địa chỉ / MST:",
            f"{data.get('dia_chi_khach','')}   |   MST: {data.get('mst_khach','')}"),
        ("Loại dịch vụ:",        loai_val),
        ("Tiến độ thực hiện:",   tien_do_val),
    ]
    # Ẩn dòng "Tiến độ" nếu không có thông tin gì (so_trang và thoi_gian đều trống)
    if not so_trang and not thoi_gian:
        kh = kh[:-1]
    for i, (label, val) in enumerate(kh):
        r = 6 + i
        _set_row(ws, r, 20)
        _mc(ws, f"A{r}:B{r}", val=label,
            fnt=_font(size=9, bold=True),
            aln=_align("left","center"),
            fll=_fill(LIGHT_GRAY),
            brd=_border())
        _mc(ws, f"C{r}:F{r}", val=val,
            fnt=_font(size=10),
            aln=_align("left","center", wrap=True),
            fll=_fill(WHITE),
            brd=_border())

    # ── Separator cam (dòng ngay sau kh list) ─────────────────────────────────
    sep_row = 6 + len(kh)
    _set_row(ws, sep_row, 5)
    _mc(ws, f"A{sep_row}:F{sep_row}", fll=_fill(ORANGE))

    # ── Header bảng (dòng kế tiếp) ────────────────────────────────────────────
    hdr_row = sep_row + 1
    _set_row(ws, hdr_row, 28)
    for col_idx, label in enumerate(["STT","HẠNG MỤC","CHI TIẾT","ĐƠN GIÁ","THÀNH TIỀN","GHI CHÚ"], 1):
        c = ws[f"{get_column_letter(col_idx)}{hdr_row}"]
        c.value = label
        c.font = _font(size=10, bold=True, color=WHITE)
        c.alignment = _align("center","center", wrap=True)
        c.fill = _fill(BLUE)
        c.border = _border()

    # ── ROWS hạng mục: tự động, auto height ───────────────────────────────────
    hang_muc_list = data.get("hang_muc", [])
    r = hdr_row + 1
    data_rows = []  # lưu để build formula tổng

    for item in hang_muc_list:
        is_sub = item.get("is_sub", False)
        bg = LIGHT_GRAY if is_sub else WHITE
        text_color = SUB_TEXT if is_sub else BLUE

        _row_h = _auto_height(item.get("chi_tiet",""), col_width_chars=60)
        _set_row(ws, r, _row_h)

        # A — STT
        c = ws[f"A{r}"]
        c.value = item.get("stt","")
        c.font = _font(size=9, bold=not is_sub)
        c.alignment = _align("center","center")
        c.fill = _fill(bg); c.border = _border()

        # B — Hạng mục
        c = ws[f"B{r}"]
        c.value = item.get("ten","")
        c.font = _font(size=9, bold=not is_sub, color=text_color)
        c.alignment = _align("left","center", wrap=True)
        c.fill = _fill(bg); c.border = _border()

        # C — Chi tiết: đầu mục IN HOA → bold, phần còn lại normal
        c = ws[f"C{r}"]
        chi_tiet = item.get("chi_tiet", "")
        # Kiểm tra có đầu mục in hoa không (dòng nào toàn chữ hoa + dấu :)
        has_headers = any(
            line.strip().rstrip(':').replace(' ','').replace('&','').isupper()
            and len(line.strip()) > 2
            for line in chi_tiet.split("\n")
            if line.strip() and not line.strip().startswith('+')
        )
        if has_headers:
            from openpyxl.cell.text import InlineFont
            from openpyxl.cell.rich_text import TextBlock, CellRichText
            bold_f   = InlineFont(rFont='Arial', b=True,  sz=9, color=DARK_TEXT)
            normal_f = InlineFont(rFont='Arial', b=False, sz=9, color=DARK_TEXT)
            blocks = []
            lines = chi_tiet.split("\n")
            for i, line in enumerate(lines):
                nl = "\n" if i < len(lines) - 1 else ""
                stripped = line.strip().rstrip(':').replace(' ','').replace('&','')
                is_header = (
                    stripped.isupper() and len(stripped) > 2
                    and not line.strip().startswith('+')
                )
                blocks.append(TextBlock(bold_f if is_header else normal_f, line + nl))
            c.value = CellRichText(*blocks)
        else:
            c.value = chi_tiet
            c.font = _font(size=9)
        c.alignment = _align("left","center", wrap=True)
        c.fill = _fill(bg); c.border = _border()

        # D — Đơn giá
        don_gia = item.get("don_gia", 0)
        c = ws[f"D{r}"]
        c.value = don_gia if don_gia != "" else None
        c.font = _font(size=9)
        c.alignment = _align("right","center")
        c.fill = _fill(bg); c.border = _border()
        c.number_format = "#,##0"

        # E — Thành tiền (= đơn giá, có thể override)
        thanh_tien = item.get("thanh_tien", don_gia)
        c = ws[f"E{r}"]
        c.value = thanh_tien
        c.font = _font(size=9)
        c.alignment = _align("right","center")
        c.fill = _fill(bg); c.border = _border()
        c.number_format = "#,##0"

        # F — Ghi chú
        c = ws[f"F{r}"]
        c.value = item.get("ghi_chu","")
        c.font = _font(size=8, color=SUB_TEXT, italic=True)
        c.alignment = _align("left","center", wrap=True)
        c.fill = _fill(bg); c.border = _border()

        data_rows.append(r)
        r += 1

    last_data_row = r - 1

    # ── Separator trước tổng ───────────────────────────────────────────────────
    _set_row(ws, r, 4)
    _mc(ws, f"A{r}:F{r}", fll=_fill(MID_GRAY))
    r += 1

    # ── Row TỔNG CỘNG ─────────────────────────────────────────────────────────
    tong_row = r
    _set_row(ws, tong_row, 30)
    _mc(ws, f"A{tong_row}:D{tong_row}",
        val="TỔNG CỘNG",
        fnt=_font(size=11, bold=True, color=WHITE),
        aln=_align("right","center"),
        fll=_fill(BLUE),
        brd=_border())

    # Formula tổng động — SUM toàn bộ cột E trong vùng hạng mục
    c = ws[f"E{tong_row}"]
    c.value = f"=SUM(E13:E{last_data_row})"
    c.font = _font(size=13, bold=True, color=WHITE)
    c.alignment = _align("right","center")
    c.fill = _fill(BLUE); c.border = _border()
    c.number_format = "#,##0"

    c = ws[f"F{tong_row}"]
    c.value = "VNĐ"
    c.font = _font(size=10, bold=True, color=WHITE)
    c.alignment = _align("center","center")
    c.fill = _fill(BLUE); c.border = _border()
    r += 1

    # ── Ghi chú gia hạn ───────────────────────────────────────────────────────
    _set_row(ws, r, 20)
    if data.get("show_renewal_note", True):
        _mc(ws, f"A{r}:F{r}",
            val="💡 Từ năm thứ 2 trở đi: chỉ phí gia hạn Domain + Hosting (tham khảo: Hosting ~859.000đ/năm, Domain ~500.000đ/năm)",
            fnt=_font(size=8, color=SUB_TEXT, italic=True),
            aln=_align("left","center", wrap=True),
            fll=_fill(LIGHT_BLUE))
        r += 1

    # ── Separator cam ──────────────────────────────────────────────────────────
    _set_row(ws, r, 5)
    _mc(ws, f"A{r}:F{r}", fll=_fill(ORANGE))
    r += 1

    # ── Header điều khoản ──────────────────────────────────────────────────────
    _set_row(ws, r, 24)
    _mc(ws, f"A{r}:F{r}",
        val="ĐIỀU KHOẢN & CHÍNH SÁCH",
        fnt=_font(size=9, bold=True, color=WHITE),
        aln=_align("left","center"),
        fll=_fill(BLUE))
    r += 1

    # ── Các dòng điều khoản — có thể override qua data["terms"] ──────────────
    default_terms = [
        f"Thời gian thực hiện: {data.get('thoi_gian','')} kể từ khi ký kết và được cấp quyền truy cập hệ thống",
        "Thanh toán: Tạm ứng 50% khi ký hợp đồng — 50% còn lại khi bàn giao hoàn chỉnh",
        "Bảo hành: 30 ngày kể từ ngày bàn giao (lỗi phát sinh từ phía HPB Media)",
        "Báo giá có hiệu lực trong 15 ngày kể từ ngày gửi",
        "Yêu cầu phát sinh ngoài phạm vi báo giá sẽ được thống nhất và báo giá bổ sung riêng",
    ]
    terms = data.get("terms", default_terms)
    payment_info = data.get("payment_info")  # dict: qr_path, bank, account_no, account_name
    terms_start_row = r
    term_cols = "A:D" if payment_info else "A:F"
    for i, term in enumerate(terms):
        _set_row(ws, r, 22)  # height cố định, đồng nhất tất cả dòng điều khoản
        bg_t = WHITE if i % 2 == 0 else LIGHT_GRAY
        _mc(ws, f"{term_cols.split(':')[0]}{r}:{term_cols.split(':')[1]}{r}",
            val=term,
            fnt=_font(size=9),
            aln=_align("left","center", wrap=False),
            fll=_fill(bg_t),
            brd=_border(top=False, left=False, right=False))
        r += 1
    terms_end_row = r - 1

    # ── Khối phương thức thanh toán (QR) — đặt bên phải các dòng điều khoản ───
    if payment_info:
        for rr in range(terms_start_row, terms_end_row + 1):
            _mc(ws, f"E{rr}:F{rr}",
                fll=_fill(LIGHT_BLUE),
                brd=_border(top=False, left=True, right=False, bottom=False))

        label_c = ws[f"E{terms_start_row}"]
        label_c.value = "PHƯƠNG THỨC THANH TOÁN"
        label_c.font = _font(size=8, bold=True, color=BLUE)
        label_c.alignment = _align("center","top")

        qr_path = payment_info.get("qr_path")
        if qr_path and os.path.exists(qr_path):
            img = XLImage(qr_path)
            img_size = 22 * 6  # px tương ứng ~6 dòng cao 22pt
            img.width = img_size
            img.height = img_size
            ws.add_image(img, f"E{terms_start_row + 1}")

        info_row = terms_end_row  # dòng cuối cùng dùng cho text ngân hàng
        bank_text = (
            f"{payment_info.get('bank','')}\n"
            f"{payment_info.get('account_name','')}\n"
            f"{payment_info.get('account_no','')}"
        )
        info_c = ws[f"E{info_row}"]
        info_c.value = bank_text
        info_c.font = _font(size=8, bold=True)
        info_c.alignment = _align("center","bottom", wrap=True)

    # ── Footer với hyperlink tel + email ──────────────────────────────────────
    _set_row(ws, r, 22)
    ws.merge_cells(f"A{r}:F{r}")
    fc = ws[f"A{r}"]
    fc.fill = _fill(BLUE)
    fc.alignment = _align("center","center")
    from openpyxl.cell.text import InlineFont
    from openpyxl.cell.rich_text import TextBlock, CellRichText
    fw = InlineFont(rFont="Arial", b=True, sz=9, color=WHITE)
    fc.value = CellRichText(
        TextBlock(fw, "Mọi thắc mắc xin liên hệ:  Phạm Văn Hưng  |  "),
        TextBlock(fw, "0913 337 280"),
        TextBlock(fw, "  |  "),
        TextBlock(fw, "hungphamcqb@gmail.com"),
    )
    # Gắn hyperlink vào cell footer (chỉ 1 link được phép trên merged cell — dùng tel)
    fc.hyperlink = "tel:+840913337280"

    # ── Print area ─────────────────────────────────────────────────────────────
    ws.print_area = f"A1:F{r}"

    wb.save(output_path)
    return output_path


